// ⏰ What's due — reports and digests follow settings.json, so no workflow edits are needed
const items = $input.all();
let settings = {};
for (let i = 0; i < items.length; i++) {
  const b = items[i].binary && items[i].binary.data;
  if (b && b.fileName === 'settings.json') settings = JSON.parse((await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8'));
}
const tz = envGet('GENERIC_TIMEZONE') || 'UTC';
const parts = Object.fromEntries(new Intl.DateTimeFormat('en-GB', { timeZone: tz, weekday: 'long', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hour12: false })
  .formatToParts(new Date()).map((p) => [p.type, p.value]));
const today = `${parts.year}-${parts.month}-${parts.day}`;
const hour = Number(parts.hour) % 24;
const hh = (t) => Number(String(t || '08:00').split(':')[0]);
const rep = settings.reports || {};
const n = settings.notifications || {};
const state = $getWorkflowStaticData('global');
let force = envGet('JOBRADAR_FORCE_REPORT');
try { const w = $('🔗 Run from CLI').first().json; force = (w.query && w.query.type) || (w.body && w.body.type) || force; } catch (e) { /* not started from the CLI */ }
const due = [];
if (['weekly', 'monthly', 'digest'].includes(force)) due.push(force);
else {
  if (rep.weekly !== false && parts.weekday.toLowerCase() === String(rep.weeklyDay || 'monday').toLowerCase() && hour === hh(rep.time) && state.weekly !== today) { due.push('weekly'); state.weekly = today; }
  if (rep.monthly !== false && parts.day === '01' && hour === hh(rep.time) && state.monthly !== today) { due.push('monthly'); state.monthly = today; }
  // the daily list runs every day: "worth a look" roles (and everything, in digest mode)
  if (hour === hh(n.digestTime) && state.digest !== today) { due.push('digest'); state.digest = today; }
}
return due.map((d) => ({ json: { due: d, reports: rep, settings } }));

// ───── helpers (generated from src/lib — edit there and rebuild) ─────
// ---- util.js : small shared helpers (inlined into n8n Code nodes) ----

function decodeEntities(s) {
  if (!s) return '';
  let out = String(s);
  // Greenhouse double-escapes (&amp;lt;) so decode twice
  for (let i = 0; i < 2; i++) {
    out = out
      .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
      .replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
      .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
      .replace(/&amp;/g, '&');
  }
  return out;
}

function htmlToText(html) {
  if (!html) return '';
  return decodeEntities(String(html))
    .replace(/<\s*(br|\/p|\/div|\/li|\/h\d|\/tr)\s*\/?>/gi, '\n')
    .replace(/<\s*li[^>]*>/gi, '\n• ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s*\n\s*\n+/g, '\n\n')
    .trim();
}

function escHtml(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function slugify(s, max) {
  const out = String(s || '')
    .normalize('NFKD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9]+/g, '-').replace(/^-+|-+$/g, '');
  return out.slice(0, max || 60);
}

function toIso(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') {
    const ms = v < 1e12 ? v * 1000 : v; // seconds vs ms
    const d = new Date(ms);
    return isNaN(d) ? null : d.toISOString();
  }
  let s = String(v).trim();
  if (/^\d{10,13}$/.test(s)) return toIso(Number(s));
  if (/^\d{4}-\d\d-\d\d \d/.test(s)) s = s.replace(' ', 'T');
  if (/^\d{4}-\d\d-\d\dT\d\d:\d\d(:\d\d(\.\d+)?)?$/.test(s)) s += 'Z'; // no timezone → assume UTC
  const d = new Date(s);
  return isNaN(d) ? null : d.toISOString();
}

function hoursSince(iso, now) {
  if (!iso) return null;
  return ((now || Date.now()) - new Date(iso).getTime()) / 36e5;
}

function humanAge(iso, now) {
  const h = hoursSince(iso, now);
  if (h === null) return 'post time unknown';
  if (h < 1) return Math.max(1, Math.round(h * 60)) + ' min ago';
  if (h < 48) return Math.round(h) + ' h ago';
  return Math.round(h / 24) + ' days ago';
}

function stripHtmlComments(md) {
  return String(md || '').replace(/<!--[\s\S]*?-->/g, '').replace(/^\s+/, '');
}

function extractHtmlComments(md) {
  const out = [];
  String(md || '').replace(/<!--([\s\S]*?)-->/g, (_, c) => { out.push(c.trim()); return ''; });
  return out.join('\n\n');
}

function truncate(s, n) {
  s = String(s || '');
  return s.length > n ? s.slice(0, n) + ' …[truncated]' : s;
}

function jobradarDir() {
  try { return (typeof $env !== 'undefined' && $env.JOBRADAR_DIR) || '/home/node/jobradar'; } catch (e) { return '/home/node/jobradar'; }
}

function envGet(k) {
  try { return (typeof $env !== 'undefined' && $env[k]) || undefined; } catch (e) { return undefined; }
}

function channelsEnabled() {
  return String(envGet('NOTIFY_CHANNELS') || 'telegram').toLowerCase().split(/[\s,]+/).filter(Boolean);
}

function shortHash(s) {
  let h = 0x811c9dc5;
  for (const ch of String(s)) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(36).toUpperCase().padStart(6, '0').slice(-6);
}

function fillCoverLetter(base, slots) {
  let txt = stripHtmlComments(base);
  for (const k of Object.keys(slots)) txt = txt.split('{{' + k + '}}').join(String(slots[k] || '').trim());
  return txt.replace(/\n{3,}/g, '\n\n').trim() + '\n';
}

function trackerRow(job, fit, extra) {
  const num = (v) => (v === null || v === undefined || isNaN(Number(v)) ? -1 : Number(v));
  return Object.assign({
    jr_id: 'JR-' + shortHash(job.uid), uid: job.uid, alt_key: job.altKey, company: job.company, title: job.title, location: String(job.location || '').slice(0, 200),
    source: job.source, url: job.url || '', apply_url: job.applyUrl || job.url || '', score: num(fit.score), skills_fit: num(fit.skills_fit), values_fit: num(fit.values_fit),
    values_note: String((fit.values_match || []).join(' · ') || fit.company_note || '').slice(0, 300),
    dream: !!job.dream, role_family: fit.role_family || '', salary: job.salary ? String(job.salary).slice(0, 120) : '',
    posted_at: job.postedAt || '', minutes_to_alert: job.postedAt ? Math.max(0, Math.round((Date.now() - new Date(job.postedAt)) / 60000)) : -1,
    applied_at: '', outcome: '', outcome_at: '',
  }, extra || {});
}

// 📊 Build reports / digest
const dues = $('⏰ What\'s due').all().map((x) => x.json);
const rows = $('🗃️ Tracker').all().map((x) => x.json).filter((r) => r && r.jr_id);
const watchRows = $input.all().map((x) => x.json).filter((r) => r && r.name);
const ch = channelsEnabled();
const to = envGet('NOTIFY_EMAIL_TO') || envGet('SMTP_USER') || '';
const out = [];
for (const d of dues) {
  if (d.due === 'digest') {
    const pend = rows.filter((r) => r.status === 'digest_pending').sort((a, b) => b.score - a.score);
    for (const e of digestEnvelopes(pend, ch, to)) out.push({ json: e });
    for (const r of pend) out.push({ json: { kind: 'row_update', row: { jr_id: r.jr_id, status: 'notified' } } });
    continue;
  }
  const R = computeReport(rows, d.due, Date.now(), d.reports);
  R.discover = discoverCompanies(rows, watchList(d.settings || {}, watchRows), Date.now() - (d.due === 'monthly' ? 30 : 7) * 864e5);
  if (ch.includes('telegram')) for (const m of telegramReport(R)) out.push({ json: m });
  if (ch.includes('email')) out.push({ json: emailReport(R, to) });
}
return out;

